var ENT=[["Double-blind trials", "Bias-killing experimental design."], ["p-values", "The debated significance gatekeeper."], ["Pre-registration", "Declaring analyses before data."], ["FAIR data", "Findable, accessible, interoperable, reusable."], ["The scientific method", "Observe, hypothesize, predict, test, revise - the loop all science shares."], ["Lab notebooks", "Contemporaneous records making experiments reproducible and defensible."], ["Peer review", "Independent expert scrutiny before publication."]];
var TECH=[["Hypothesis framing", "Falsifiable predictions with measurable outcomes."], ["Randomized assignment", "Breaking confounding by chance allocation."], ["Blinding", "Hiding assignments from subjects, experimenters or analysts."], ["Replication", "Repeating experiments to test robustness of findings."], ["Calibration", "Comparing instruments against known standards."], ["Uncertainty quantification", "Propagating measurement error to conclusions."], ["Literature review", "Mapping prior work before claiming novelty."], ["Negative controls", "Checks that must fail if the method works."], ["Power analysis", "Sizing samples to detect effects worth finding."], ["Open data", "Publishing datasets enabling independent verification."]];
